78	// calculateTokenUsage is a test helper that looks up an agent by type and
79	// calculates token usage from pre-loaded transcript bytes.
80	func calculateTokenUsage(agentType types.AgentType, data []byte, offset int) *agent.TokenUsage {
81		ag, err := agent.GetByAgentType(agentType)
82		if err != nil {
83			return nil
84		}
85		return agent.CalculateTokenUsage(context.Background(), ag, data, offset, "")
86	}
