88	func TestCalculateTokenUsage_CursorReturnsNil(t *testing.T) {
89		t.Parallel()
90	
91		// Cursor transcripts don't contain token usage data, so CalculateTokenUsage
92		// should return nil (not an empty struct) to signal "no data available".
93		transcript := []byte(`{"role":"user","message":{"content":[{"type":"text","text":"hello"}]}}`)
94	
95		ag, err := agent.GetByAgentType(agent.AgentTypeCursor)
96		if err != nil {
97			t.Fatalf("GetByAgentType(Cursor) error: %v", err)
98		}
99		result := agent.CalculateTokenUsage(context.Background(), ag, transcript, 0, "")
100		if result != nil {
101			t.Errorf("CalculateTokenUsage(Cursor) = %+v, want nil", result)
102		}
103	}
