gh api repos/entireio/cli/pulls/980/comments --paginate --jq '[.[] | {id: .id, author: .user.login, path: .path, line: (.line // .original_line), body: .body, in_reply_to_id: .in_reply_to_id, created_at: .created_at}]' 2>&1 | python3 -c "
import json, sys
comments = json.load(sys.stdin)

# Build threads
threads = {}
replies = {}
for c in comments:
    if c['in_reply_to_id']:
        replies.setdefault(c['in_reply_to_id'], []).append(c)
    else:
        threads[c['id']] = c

# Filter unresolved: last reply doesn't indicate resolution
unresolved = []
for tid, root in threads.items():
    thread_replies = replies.get(tid, [])
    if thread_replies:
        last = thread_replies[-1]
        body_lower = last['body'].lower()
        if any(w in body_lower for w in ['fixed in', 'addressed in', 'updated in', 'documented in', 'already handled', 'no longer applicable', 'not applicable']):
            continue
    unresolved.append({'root': root, 'replies': replies.get(tid, [])})

for u in unresolved:
    r = u['root']
    print(f\"ID: {r['id']}\")
    print(f\"Author: {r['author']}\")
    print(f\"File: {r['path']}:{r['line']}\")
    print(f\"Body: {r['body'][:300]}\")
    print(f\"Replies: {len(u['replies'])}\")
    print('---')
"

